/**
 * AiProviderConnectionEntityMapper — TASK-958 round-trip + OCC-guard tests.
 *
 * Two properties, both easy to lose silently:
 *
 *  - the three TASK-958 columns (`slug`, `name`, `defaultForProvider`) survive
 *    both directions. The mapper is auto-generated by NAME, so a field missing
 *    from the entity or the model does not fail to compile — it simply stops
 *    round-tripping, and a connection would persist with a slug the caller
 *    never chose;
 *  - `_version` is STILL stripped from both write paths. This model is
 *    OCC-written, `FIELDS_NOT_WRITABLE = ['version']` is the only thing
 *    stopping a mapper-written `_version` leaking into a Prisma update, and
 *    running `gen:mapper` would delete that strip (it is why the command is
 *    banned). This suite is what notices.
 */
/* eslint-disable @typescript-eslint/no-explicit-any */
import { describe, it, expect } from 'vitest';
import { AiProviderConnectionEntityMapper } from '../AiProviderConnectionEntityMapper';
import { AiProviderConnection } from '../../../../models/generated/core/AiProviderConnectionModel';
import { ResourceStatusType } from '../../../../enums/generated/ResourceStatusType';

const sampleRow = (overrides: Partial<AiProviderConnection> = {}): AiProviderConnection =>
  new AiProviderConnection({
    id: 'conn-1',
    tenantId: 't-1',
    service: 'llm',
    provider: 'openai',
    slug: 'openai-research',
    name: 'Research account',
    defaultForProvider: null,
    baseUrl: null,
    region: null,
    apiVersion: null,
    deploymentName: null,
    encryptedApiKey: null,
    keyVersion: null,
    enabled: true,
    extraJson: null,
    maxConcurrent: null,
    rpmLimit: null,
    tpmLimit: null,
    timeoutS: null,
    resourceStatus: ResourceStatusType.ENABLED,
    resourceStatusUpdatedAt: null,
    resourceStatusUpdatedBy: null,
    createdBy: null,
    updatedBy: null,
    createdAt: new Date(),
    updatedAt: new Date(),
    version: 5,
    metaData: null,
    ...overrides,
  } as AiProviderConnection);

describe('AiProviderConnectionEntityMapper', () => {
  const mapper = new AiProviderConnectionEntityMapper();

  it('toDomainEntity carries slug, name and defaultForProvider off the row', () => {
    const entity = mapper.toDomainEntity(sampleRow());
    expect(entity.slug).toBe('openai-research');
    expect(entity.name).toBe('Research account');
    expect(entity.defaultForProvider).toBeNull();
    expect(entity.isDefault).toBe(false);
    expect(entity.version).toBe(5);
  });

  it('reads a DEFAULT row as default', () => {
    const entity = mapper.toDomainEntity(sampleRow({ slug: 'openai', defaultForProvider: 'openai' } as any));
    expect(entity.isDefault).toBe(true);
  });

  it('round-trips the three columns entity → persistence', () => {
    const persisted = mapper.toPersistence(mapper.toDomainEntity(sampleRow()));
    expect(persisted.slug).toBe('openai-research');
    expect(persisted.name).toBe('Research account');
    expect(persisted.defaultForProvider).toBeNull();
    expect(persisted.provider).toBe('openai');
  });

  it('toPersistence (full insert path) does not write `version`', () => {
    const persisted = mapper.toPersistence(mapper.toDomainEntity(sampleRow({ version: 1 } as any)));
    expect(persisted).not.toHaveProperty('version');
  });

  it('toPersistenceChanges never contains `version`, even if the change set has it', () => {
    const entity = mapper.toDomainEntity(sampleRow());
    (entity as any)._changes = { defaultForProvider: 'openai', version: 99 };
    const persisted = mapper.toPersistenceChanges(entity);
    expect(persisted).not.toHaveProperty('version');
    expect(persisted.defaultForProvider).toBe('openai');
  });
});
